select case when budget >= 3241000 then 'high' when budget >= 1885000 then 'mid' else 'low' end as budget_bucket, dept_name, max(budget) - min(budget) as budget_range from departments group by case when budget >= 3241000 then 'high' when budget >= 1885000 then 'mid' else 'low' end, dept_name order by dept_name, budget_range desc, budget_bucket limit 3;
